import React from 'react';
import './Offers.css';
import { useNavigate } from 'react-router-dom';

const Offers = () => {
  const navigate = useNavigate();

  return (
    <section className="offers4">

      <div className="offers4-card">

        <div className="offers4-left">
          <h2>Special Offer</h2>
          <p>
            Get exclusive fashion deals with premium quality products
            made for your everyday style.
          </p>

          <div className="offers4-buttons">
            <button onClick={() => navigate('/womens')}>
              Women
            </button>

            <button onClick={() => navigate('/mens')}>
              Men
            </button>
          </div>
        </div>

        <div className="offers4-right">
          <h1>UP TO <span>50%</span> OFF</h1>
          <p>Limited time only</p>
        </div>

      </div>

    </section>
  );
};

export default Offers;
